import {TIMINGS,demoURL,formatTime} from './config.js';
const $=s=>document.querySelector(s),slides=[...document.querySelectorAll('.slide')];
const NOTES=[
`0:00–0:30 / THE PROBLEM\n\nA smoke signal is useful only if someone can turn it into a responsible next step. An operator needs to compare different observations, understand route constraints, and prepare a message that can be reviewed. I built PHAROS to make that handoff visible. This is a working wildfire exercise prototype focused on climate resilience, not a deployed emergency system.`,
`0:30–1:00 / THE WORKFLOW\n\nPHAROS brings three steps into one workspace. First, gather evidence while keeping its provenance and uncertainty. Second, check route candidates against the hazard geometry we have. Third, prepare a message that a named person must review. The model is not deciding that a road is safe or issuing an evacuation order. Let me show you the actual product.`,
`1:00–2:25 / LIVE DEMO — KEEP MOVING\n\n[0–15s] Click a camera evidence row, show its source ID, then close it. “These observations are explicit replay fixtures. Camera and thermal observations remain separate signals.”\n\n[15–30s] Point to Ridge Road and Canyon Connector. “One intersects our supplied hazard; one passes this specific check. Passing geometry does not prove road safety.”\n\n[30–55s] Click Prepare draft. “This demonstration uses a labeled local template. The source references and route limitations remain visible.”\n\n[55–75s] Enter Pratik Balaji, check the review box, and approve. Click Send test notification. “This records a test in the local inbox; no emergency message is sent.”\n\n[75–85s] “Now let's change the situation.” Advance using the deck’s bottom-right arrow.`,
`2:25–3:10 / THE FAILURE CASE\n\nThe closure scenario loads when this slide opens. If the controls have not connected, use Run scenario → Road closure inside the app.\n\n“Both candidates now intersect the supplied scenario zones. The previous draft and approval have been cleared.”\n\nClick Prepare draft. “The new message withholds route instructions. This is the behavior I want to demonstrate: changing evidence must change what the system is willing to say.”\n\nIf time remains, open Activity in the app to show the invalidation event.`,
`3:10–4:10 / IMPLEMENTATION\n\nThe browser uses MapLibre. Python services provide scenario facts and deterministic route checks. The backend stores drafts, approvals and audit records in SQLite.\n\nI also implemented a Bedrock Converse tool loop and a separate read-only MCP server. They share the same service functions; Bedrock is not yet calling the server over MCP transport.\n\nFIRMS, weather and OSRM adapters, plus ntfy delivery, are implemented but require configuration. They are not fused into the replay you just saw. The baseline has 19 automated checks across geometry, workflow and mocked model responses. That verifies specific software behavior, not detection accuracy or field readiness.`,
`4:10–4:50 / CLOSE — LEAVE TEN SECONDS\n\nThe sustainability goal is wildfire resilience: help operators turn scattered observations into communication they can inspect and stand behind. The next steps are validated smoke inference, authoritative road and hazard data, and live-feed fusion. Then I want to measure drafting time, unsupported claims and review quality with operators. PHAROS already demonstrates the review workflow and the refusal to invent a route when the checks fail. Thank you.`
];
const LABELS=['THE PROBLEM','THE WORKFLOW','LIVE / EVIDENCE → ALERT','LIVE / CONDITIONS CHANGE','IMPLEMENTATION','CLIMATE RESILIENCE'];
let slide=Math.max(0,Math.min(5,(Number(location.hash.slice(1))||1)-1)),running=false,elapsed=0,started=0,embedReady=false,desiredCommand=null,timeout;
const frame=$('#app-frame');let configured='';try{configured=localStorage.getItem('pharos-deck-url')||''}catch{}
let activeURL;
function configure(value){activeURL=demoURL(value,location.href);embedReady=false;$('#connection-status').textContent='Connecting actual app…';$('#embed-help').hidden=true;frame.src=activeURL.href;$('#open-app').href=activeURL.href;$('#fallback-link').href=activeURL.href;clearTimeout(timeout);timeout=setTimeout(()=>{if(!embedReady){$('#connection-status').textContent='Manual demo / controls not connected';$('#embed-help').hidden=false}},10000);}
function send(command){if(command!=='ping')desiredCommand=command;frame.contentWindow?.postMessage({type:'PHAROS_PRESENTATION',command},activeURL.origin);}
window.addEventListener('message',event=>{if(event.origin!==activeURL.origin||event.source!==frame.contentWindow||event.data?.type!=='PHAROS_PRESENTATION_ACK')return;const first=!embedReady;embedReady=true;clearTimeout(timeout);$('#embed-help').hidden=true;$('#connection-status').textContent='APP CONNECTED / ISOLATED EXERCISE';if(first&&desiredCommand)send(desiredCommand);});
frame.addEventListener('load',()=>send('ping'));
function resizeFrame(){const box=$('.frame-slot').getBoundingClientRect();if(!box.width||!box.height)return;const scale=Math.min(box.width/1280,box.height/800);frame.style.transform=`translateX(${-640*scale}px) scale(${scale})`;}
new ResizeObserver(resizeFrame).observe($('.frame-slot'));
function go(index,updateHash=true){const previous=slide;slide=Math.max(0,Math.min(5,index));slides.forEach((s,i)=>{s.hidden=i!==slide;s.setAttribute('aria-hidden',String(i!==slide))});$('#slide-number').textContent=String(slide+1).padStart(2,'0');$('#section-name').textContent=LABELS[slide];$('#notes-text').textContent=NOTES[slide];$('#prev').disabled=slide===0;$('#next').disabled=slide===5;$('#dots').querySelectorAll('button').forEach((b,i)=>{b.classList.toggle('active',i===slide);b.setAttribute('aria-current',i===slide?'step':'false')});const before=TIMINGS.slice(0,slide).reduce((a,b)=>a+b,0);$('#target-time').textContent=`TARGET ${formatTime(before)}–${formatTime(before+TIMINGS[slide])}`;$('#live-demo').hidden=![2,3].includes(slide);if(![2,3].includes(slide))$('#live-demo').classList.remove('expanded');$('#expand-demo').textContent=$('#live-demo').classList.contains('expanded')?'Collapse':'Expand';if(slide!==previous||!desiredCommand){if(slide===2)send('reset');if(slide===3)send('closure');}resizeFrame();if(updateHash)history.replaceState(null,'','#'+(slide+1));}
$('#dots').innerHTML=slides.map((_,i)=>`<button aria-label="Go to slide ${i+1}" data-slide-index="${i}"></button>`).join('');$('#dots').addEventListener('click',e=>{if(e.target.dataset.slideIndex)go(Number(e.target.dataset.slideIndex))});$('#prev').onclick=()=>go(slide-1);$('#next').onclick=()=>go(slide+1);
function clock(){const total=elapsed+(running?(performance.now()-started)/1000:0);const remaining=300-total;$('#timer-toggle').textContent=total===0&&!running?'Start 5:00':`${running?'Ⅱ':'▶'} ${remaining<0?'+':''}${formatTime(remaining)}`;$('#timer-toggle').setAttribute('aria-label',`${running?'Pause':'Start'} rehearsal timer`);document.body.classList.toggle('overtime',remaining<0);$('#progress').style.width=`${Math.min(100,total/300*100)}%`;}
$('#timer-toggle').onclick=()=>{if(running)elapsed+=(performance.now()-started)/1000;else started=performance.now();running=!running;clock()};$('#timer-reset').onclick=()=>{running=false;elapsed=0;clock()};setInterval(clock,250);
function toggleNotes(){const notes=$('#notes');notes.hidden=!notes.hidden;$('#notes-button').setAttribute('aria-pressed',String(!notes.hidden))}$('#notes-button').onclick=toggleNotes;$('#hide-notes').onclick=toggleNotes;
$('#fullscreen-button').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{$('#fullscreen-button').title='Fullscreen unavailable; use your browser fullscreen command.'}};
$('#expand-demo').onclick=()=>{const expanded=$('#live-demo').classList.toggle('expanded');$('#expand-demo').textContent=expanded?'Collapse':'Expand';resizeFrame()};
document.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>{if(!embedReady){$('#embed-help').hidden=false;return}send(b.dataset.command)});
document.addEventListener('keydown',e=>{if($('#settings').open||e.target.closest('input,textarea,select,button,a'))return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();go(slide+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();go(slide-1)}if(e.key.toLowerCase()==='n')toggleNotes();if(e.key==='Escape'&&$('#live-demo').classList.contains('expanded')){$('#live-demo').classList.remove('expanded');$('#expand-demo').textContent='Expand';resizeFrame()}});
window.addEventListener('hashchange',()=>go((Number(location.hash.slice(1))||1)-1,false));
$('#settings-button').onclick=()=>{$('#demo-url').value=configured;$('#settings-error').textContent='';$('#settings').showModal()};$('#close-settings').onclick=()=>$('#settings').close();
function saveURL(value){configure(value);configured=value;try{localStorage.setItem('pharos-deck-url',value)}catch{}$('#settings').close();if(slide===2)desiredCommand='reset';else if(slide===3)desiredCommand='closure';}
$('#settings-form').onsubmit=e=>{e.preventDefault();try{saveURL($('#demo-url').value.trim())}catch(error){$('#settings-error').textContent=error.message}};$('#restore-demo').onclick=()=>saveURL('');
try{configure(configured)}catch{configured='';configure('')}go(slide);clock();
